#pragma once
// C2 death animations: die1/die2 of the *_dead objects (data.js), 8 fps, no loop; the last
// frame stays as the corpse. Table generated by tools/extract_die_anims.py.
namespace mdaz {
struct DieFrame { const char* sheet; int x, y, w, h; float hx, hy; };
struct DieAnim { const char* key; int style; int speed; int count; DieFrame f[6]; };
// key: zed skin base (zed_normal_skin1, ...) or wolf / deer / rabbit / dog. style 1 = die1, 2 = die2.
const DieAnim* die_anim_find(const char* key, int style);
// Seconds the animation plays (count / speed); 0 when the object has no played animation.
float die_anim_seconds(const DieAnim* a);
const DieFrame* die_anim_frame(const DieAnim* a, float elapsed);
} // namespace mdaz
